/*////////////////////////////////////////////////////////////////////////////////////////////////////


    OBJECT ROTATOR WIDGET
    --------------------------------------------------------------------------------------------------    

    Function:    

    A lightweight Shadertoy utility that allows objects to be rotated in 3D space in a stable, intuitive and persistent way.
    This demo reveals the derived rotation plane (green halo) and axis (blue cylinder) based on mouse clicking and dragging.


    Requirements:

    A simple ray tracer capable of testing for ray-object intersections.


    Use:

    This widget leverages data from the ray tracer to calculate the intersection of a mouse ray with a designated manipulable object.
    It then computes an axis/angle rotation based on the movement of the mouse before deriving the required compound transforms. 
    These transforms are stored as unit quaternions in a series of state texels in the bottom-left corner of the framebuffer.   

    For a minimal version that's easy to implement into a project, see shadertoy.com/view/XXycWz


////////////////////////////////////////////////////////////////////////////////////////////////////*/


// Applies an LCD post-processing effect to the value of rgb based on the screen coordinate
vec3 LCD(vec3 rgb, vec2 xyScreen)
{
    vec2 xyPixel = mod(xyScreen, vec2(kScreenDownsample));
    vec2 xySubpixel = mod(xyPixel, vec2(float(kScreenDownsample) / 3.0, kScreenDownsample));   
    int subPixelIdx = int(xyPixel.x / (float(kScreenDownsample) / 3.0));
    vec2 xyDot = ((xySubpixel - vec2(kScreenDownsample) / vec2(6.0, 2.0)) / (vec2(kScreenDownsample) / vec2(6.0, 2.0))) * vec2(1.5, 1.2);
    xyDot = sign(xyDot) * pow(abs(xyDot), vec2(1.5, 3.0));
    float dist = max(0.0, 1.0 - length(xyDot) / 2.8);
    rgb *= dist;

    rgb[(subPixelIdx+1)%3] *= 0.5;
    rgb[(subPixelIdx+2)%3] *= 0.5;

    return rgb;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{        
    //rgba = texelFetch(iChannel1, ivec2(xyScreen), 0); return;

    #define kGamma vec3(1.5)
    #define kGain vec3(1.0)
    #define kLift 0.1

    // Composite render output
    rgba.xyz = kGain * pow(texelFetch(iChannel0, ivec2(xyScreen) / kScreenDownsample, 0).xyz, 1. / kGamma);
    rgba.w= 1.;




    // Add the bloom effect
    vec3 bloom = kZero;
    if(kApplyBloom) { bloom = SeparableBlurUp(ivec2(xyScreen), ivec2(iResolution.xy), iChannel1); }

    rgba.xyz += bloom;
    rgba.xyz = rgba.xyz * 10.;
    rgba.x = floor(rgba.x) + float(OrderedDither(ivec2(xyScreen) / kScreenDownsample) < fract(rgba.x));
    rgba.y = floor(rgba.y) + float(OrderedDither((2 + ivec2(xyScreen)) / kScreenDownsample) < fract(rgba.y));
    rgba.z = floor(rgba.z) + float(OrderedDither((4 + ivec2(xyScreen)) / kScreenDownsample) < fract(rgba.z));
    rgba.xyz /= 10.;    

    // Apply LCD post-processing effect
    rgba.xyz = LCD(mix(vec3(kLift), kOne, rgba.xyz), xyScreen);

        rgba.xyz += bloom * 0.7;


    // Show state params
    //if(xyScreen.y < 50.) { rgba.xyz += texelFetch(iChannel2, ivec2(xyScreen) / 50, 0).xyz; }
 }

// Ray-plane intersection test
bool RayPlane(inout Ray ray, bool bounded, float extent, inout HitCtx hit, in Transform transform)
{
    RayBasic localRay = RayToObjectSpace(ray.od, transform);
    if(abs(localRay.d.z) < 1e-10) { return false; } 

    float t = localRay.o.z / -localRay.d.z;
    if (t <= 0.0 || t >= ray.tNear) { return false; }

    float u = (localRay.o.x + localRay.d.x * t) / extent + 0.5;
    float v = (localRay.o.y + localRay.d.y * t) / extent + 0.5;

    if(bounded && (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0)) { return false; }   

    ray.tNear = t;
    SetRayFlag(ray, kFlagsBackfacing, localRay.o.z < 0.0);
    hit.n = transpose(transform.rot) * vec3(0.0, 0.0, 1.0);
    hit.uv = vec2(u, v);

    return true;
}

// Ray-cylinder intersection test
bool RayCylinder(inout Ray ray, inout HitCtx hit, in Transform transform, float height)
{
    RayBasic localRay = RayToObjectSpace(ray.od, transform);

    // A ray intersects a sphere in at most two places which means we can find t by solving a quadratic
    float a = dot(localRay.d.xy, localRay.d.xy);
    float b = 2.0 * dot(localRay.d.xy, localRay.o.xy);
    float c = dot(localRay.o.xy, localRay.o.xy) - 1.0;

    // Intersect the unbounded cylinder
    vec2 tNearCyl, tFarCyl;
    if(!QuadraticSolve(a, b, c, tNearCyl.x, tFarCyl.x)) { return false; }    
    sort(tNearCyl.x, tFarCyl.x);

    // Intersect the caps
    tNearCyl.y = (-height * 0.5 - localRay.o.z) / localRay.d.z;
    tFarCyl.y = (height * 0.5 - localRay.o.z) / localRay.d.z;    
    sort(tNearCyl.y, tFarCyl.y);

    float tNearMax = max(tNearCyl.x, tNearCyl.y);
    float tFarMin = min(tFarCyl.x, tFarCyl.y);
    if(tNearMax > tFarMin) { return false; }  // Ray didn't hit 

    float tNear;
    if(tNearMax > 0.0 && tNearMax < ray.tNear) { tNear = tNearMax; }
    else if(tFarMin > 0.0 && tFarMin < ray.tNear) { tNear = tFarMin; }
    else { return false; } // Box is behind the ray

    vec3 i = localRay.o + localRay.d * tNear;

    ray.tNear = tNear;
    if(tNearCyl.x < tNearCyl.y)
    {
        hit.n = vec3(0.0, 0.0, sign(i.z));
        hit.uv = vec2(1. + atan(i.y, i.x) / kHalfPi, length(i.xy));
    }
    else
    {
        hit.n = vec3(i.xy, 0.);
        hit.uv = vec2(1. + atan(i.y, i.x) / kHalfPi, i.z / kHalfPi);
    }    
    hit.n = transpose(transform.rot) * hit.n;
    SetRayFlag(ray, kFlagsBackfacing, dot(localRay.o, localRay.o) < 1.0);

    return true;
}

vec3 RayPerpendicularPoint(in RayBasic ray, in vec3 point)
{
    return PointAt(ray, dot(point, ray.d) - dot(ray.o, ray.d));
}

mat3 PinholeCameraViewMatrix(vec3 cameraPos, vec3 cameraLookAt)
{
    return CreateBasis(normalize(cameraPos - cameraLookAt), vec3(0., 1., 0.));
}

Ray CreatePinholeCameraRay(vec2 uvScreen, vec3 cameraPos, vec3 cameraLookAt)
{   
    #define kCameraFoV          40.
    Ray ray;
    ray.od.o = cameraPos;
    ray.od.d = transpose(PinholeCameraViewMatrix(cameraPos, cameraLookAt)) * normalize(vec3(uvScreen, -1. / tan(toRad(kCameraFoV))));
    ray.tNear = kFltMax;
    ray.weight = vec3(1.0, 1.0, 1.0);
    ray.flags = kFlagsCausticPath;
    ray.depth = 0;

    return ray;  
}

vec3 PinholeCameraProjectPoint(vec3 p, vec3 cameraPos, vec3 cameraLookAt)
{
    // Transform the point into the basis of the camera sensor
    p = PinholeCameraViewMatrix(cameraPos, cameraLookAt) * (p - cameraPos);

    return p / (p.z / -tan(toRad(kCameraFoV)));
}

#define kInvalidMaterial -1
#define kMatGrid 0
#define kMatRotAxis 1
#define kMatDragAxis 2
#define kMatHalo 3
#define kMatManipulatorObject 4

// Trace axis-aligned cylinders and grids for reference
int Trace(inout Ray ray, out HitCtx hit, vec3 cameraPos)
{
    Transform transform;
    hit.matID = kInvalidMaterial;   

    #define kAxisScale (1. / 200.)

    transform = CompoundTransform(vec3(0.), vec3(kHalfPi, 0., 0.), kAxisScale);
    Ray tempRay = ray;
    HitCtx tempHit;
    if(RayPlane(tempRay, true, 1. / kAxisScale, tempHit, transform)) 
    { 
        #define kGridThickness 0.05
        #define kGridSubdiv 10.
        vec2 uvFract = fract(tempHit.uv * (kGridSubdiv + kGridThickness));
        if((uvFract.x < kGridThickness || uvFract.y < kGridThickness) && fract((uvFract.x + uvFract.y) * kGridSubdiv * 0.5) < 0.5)
        {        
            tempHit.matID = kMatGrid; 
            tempHit.n = -ray.od.d;
            ray = tempRay;
            hit = tempHit;
        }
    }  

    // Draw the manipulator axes and gimbal. This is for illustration purposes and doesn't 
    // need to be included when using the widget.
#ifdef kShowManipulatorGimbals
    float gimbalAlpha = smoothstep(0., 1., texelFetch(iChannel0, ivec2(0), 0).w);
    if(gimbalAlpha > 0.)
    {                       

        // Base axis
        transform.rot = LoadManipulatorMatrix(iChannel0, kStateGimbalQuatA);
        transform.sca = 0.01;
        transform.pos = kZero;
        if(RayCylinder(ray, hit, transform, gimbalAlpha / transform.sca)) { hit.matID = kMatDragAxis; } 

        // Rotation axis
        transform.rot = LoadManipulatorMatrix(iChannel0, kStateGimbalQuatB);
        tempRay = ray;
        if(RayPlane(tempRay, true, 0.5 / kAxisScale, tempHit, transform))
        {
            tempHit.uv -= 0.5;
            float lenHit = length(tempHit.uv);
            if(lenHit > 0.45 && lenHit < 0.5 && abs(atan(-tempHit.uv.y, tempHit.uv.x)) < kPi * gimbalAlpha)
            {
                ray = tempRay;
                hit = tempHit;
                hit.matID = kMatHalo;
            }
        }            

        if(RayCylinder(ray, hit, transform, gimbalAlpha / transform.sca)) { hit.matID = kMatRotAxis; }            
    }
#endif

    // Load the object transformation matrix from kStateDragMatrix
    transform.rot = LoadManipulatorMatrix(iChannel0, kStateDragQuat);    
    transform.pos = kZero;
    transform.sca = 0.25;        

    // Trace the manipulated object. If the ray hits, it must be appropriately flagged     
    // so that the computd hit point can be stored in the state variable and reused later.
    if(RayCylinder(ray, hit, transform, 2.0)) { hit.matID = kMatManipulatorObject; }  

    return hit.matID;
}


void mainImage( out vec4 fragRgba, in vec2 xyScreen)
{   
    fragRgba *= 0.;
    ivec2 xyPixel = ivec2(xyScreen);

    // Automate the mouse movement for the first few seconds to demo the manipulator
    #define kIntroInterval 180
    #define kIntroDelay 20
    vec4 mouse = iMouse;
    if(iFrame < kIntroInterval)
    {
        float theta = 1.2 * kTwoPi * smoothstep(0., 1., float(iFrame - kIntroDelay) / float(kIntroInterval - kIntroDelay));
        float phi = 1. * kTwoPi * smoothstep(0., 1., float(iFrame - kIntroDelay) / float(kIntroInterval - kIntroDelay));
        mouse.xy = iResolution.xy * 0.5 + iResolution.x * 0.1 * vec2(cos(theta), sin(phi));
        mouse.z = float(iFrame >= kIntroDelay);
        mouse.w = float(iFrame == kIntroDelay);
    }        

    // Define the camera properties
    #define kCameraPhi (kTwoPi * mix(-1., 1., 0.2))
    #define kCameraTheta (kPi * mix(0.01, 0.99, 0.35))
    #define kCameraDist 1.3
    vec3 cameraPos = vec3(sin(kCameraTheta) * cos(kCameraPhi), cos(kCameraTheta), sin(kCameraTheta) * sin(kCameraPhi)) * kCameraDist;
    vec3 cameraLookAt = vec3(0., -0.05, 0.);

    // Create the manipulator context here. Its parameters are defined as follows:
    // cameraPos: the position of the camera
    // objectPos: the position of object we want to manipulate
    // initMat: the initial value of the object's rotation matrix 
    // speed: the rate of rotation for a given drag distance

    ManipulatorCtx maniCtx;
    maniCtx.cameraPos = cameraPos;
    maniCtx.objectPos = kZero;
    maniCtx.initMat = RotXMat3(1.3);
    maniCtx.speed = 6.;

    // The manipulator state is stored in texels at the bottom-left corner of the frame buffer.
    // If this fragment is associated with a state value, its value (defined in fragRgba) 
    // will be automatically updated. The shader op can then be terminated.

    if(UpdateManipulatorState(iChannel0, iFrame, xyScreen, maniCtx, mouse, fragRgba)) { return; }   

    // Create a camera ray
    RenderCtx renderCtx;
    renderCtx.xyScreen = ivec2(xyScreen);    
    vec2 uvView = ScreenToNormalisedScreen(xyScreen, iResolution.xy);    
    Ray ray = CreatePinholeCameraRay(uvView, cameraPos, cameraLookAt);       

    // Trace and shade the ray 
    vec3 L = kZero;
    HitCtx hit; 
    if(Trace(ray, hit, cameraPos) != kInvalidMaterial)
    {             
        switch(hit.matID)
        {
            case kMatManipulatorObject:
                L = 1. * vec3(1., 0.6, 0.) * float((int(round(fract(hit.uv.x * 2.))) + int(round(fract(hit.uv.y * 2.)))) % 2);
                break;
            case kMatRotAxis:
                L = vec3(0., 0.2, 1.0);  break;
            case kMatDragAxis:
                L = vec3(1., 0., 0.2);  break;
            case kMatHalo:
                L = vec3(0.2, 1.0, 0.05);  break;
            default:
                L = vec3(0.7); 
        };        
    }         

    // The manipulator needs the ray origin, direction and object hit point belonging 
    // to the pixel under the mouse. By this point this information should be stored
    // in the Ray data structure, so if this pixel is associated with a state parameter,
    // write its value to the framebuffer now.

    if(IsMouseStateParam(xyPixel))
    {        
        switch(xyPixel.x)
        {
            // Ray position
            case kStateMouseRayPos: fragRgba.xyz = ray.od.o; break;
            // Ray direction
            case kStateMouseRayDir: fragRgba = vec4(ray.od.d, ray.tNear); break;
            // Object hit point
            case kStateMouseHitPoint: 
            {
                fragRgba.w = float(mouse.w > 0. && hit.matID == kMatManipulatorObject);
                if(mouse.w > 0.) { fragRgba.xyz = PointAt(ray); }
                break;
            }
        }
    }
    else
    {  
        // Otherwise, write out the result from the renderer
        fragRgba = vec4(L, 1.0f);
    }   
}

