void SetRayFlag(inout Ray ray, in uint flag, in bool set)
{
    ray.flags = (ray.flags & ~flag) | uint(set);
}

void CreateRay(inout Ray ray, vec3 o, vec3 d, vec3 kickoff, vec3 weight, int depth, uint flags)
{     
    ray.od.o = o + kickoff;
    ray.od.d = d;
    ray.tNear = kFltMax;
    ray.weight = weight;
    ray.flags = flags;
    ray.depth = depth;
}

vec3 PointAt(Ray ray) { return ray.od.o + ray.od.d * ray.tNear; }
vec3 PointAt(RayBasic ray, float t) { return ray.o + ray.d * t; }

struct Transform
{
    vec3 pos;
    mat3 rot;
    float sca;
};

RayBasic RayToObjectSpace(in RayBasic world, in Transform transform) 
{
	RayBasic object;
	object.o = world.o - transform.pos;
	object.d = world.d + object.o;
	object.o = transform.rot * object.o / transform.sca;
	object.d = (transform.rot * object.d / transform.sca) - object.o;
	return object;
}

mat3 Identity()
{
    return mat3(vec3(1.0, 0.0, 0.0), vec3(0.0, 1.0, 0.0), vec3(0.0, 0.0, 1.0));
}

mat3 ScaleMat3(float scale)
{
    float invScale = 1.0f / scale;
	return mat3(vec3(invScale, 0.0, 0.0),
			vec3(0.0, invScale, 0.0),
			vec3(0.0, 0.0, invScale));
}

mat3 RotXMat3(float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
	return mat3(vec3(1.0, 0.0, 0.0),
			vec3(0.0, cosTheta, -sinTheta),
			vec3(0.0, sinTheta, cosTheta));
}

mat3 RotYMat3(const float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
	return mat3(vec3(cosTheta, 0.0, sinTheta),
			vec3(0.0, 1.0, 0.0),
			vec3(-sinTheta, 0.0, cosTheta));
}

mat3 RotZMat3(const float theta)
{
    float cosTheta = cos(theta), sinTheta = sin(theta);
	return mat3(vec3(cosTheta, -sinTheta, 0.0),
			vec3(sinTheta, cosTheta, 0.0),
			vec3(0.0, 0.0, 1.0));
}

Transform CompoundTransform(vec3 pos, vec3 rot, float scale)
{
    Transform t;
    t.rot = Identity();
    t.sca = scale;
    t.pos = pos;

    if (rot.x != 0.0) { t.rot *= RotXMat3(rot.x); }
    if (rot.y != 0.0) { t.rot *= RotYMat3(rot.y); }
    if (rot.z != 0.0) { t.rot *= RotZMat3(rot.z); }

    //if (scale != 1.0f) { t.rot *= ScaleMat3(scale); }

    return t;
}

Transform IdentityTransform()
{
    Transform t;
    t.rot = Identity();
    t.sca = 1.0;
    t.pos = kZero;
    return t;
}

vec2 ScreenToNormalisedScreen(vec2 p, vec2 iRes)
{   
    return (p - vec2(iRes) * 0.5) / float(iRes.y); 
}

// *******************************************************************************************************
//    Bloom filter
// *******************************************************************************************************

#define kApplyBloom true 
#define kBloomRadius vec2(0.05)
#define kBloomKernelShape vec3(1.)
#define kBloomBurnout vec3(0.2)
#define kBloomDownsample 5

void Gaussian(in int k, in int radius, in vec3 rgbK, in vec3 kernelShape, inout vec3 sigmaL, inout vec3 sigmaWeights)
{
    float d = float(abs(k)) / float(radius);
    vec3 weight = pow(max(vec3(0.), (exp(-sqr(vec3(d) * 4.0)) - 0.0183156) / 0.981684), kernelShape);         

    sigmaL += rgbK * weight;
    sigmaWeights += weight;
}

void Epanechnikov(in int k, in int radius, in vec3 rgbK, in vec3 kernelShape, inout vec3 sigmaL, inout vec3 sigmaWeights)
{
    float d = float(abs(k)) / float(radius);
    float weight = 1. - d*d;

    sigmaL += rgbK * weight;
    sigmaWeights += weight;
}

//#define BlurKernel Gaussian
#define BlurKernel Epanechnikov

vec3 SeparableBlurDown(ivec2 xy, ivec2 res, sampler2D sampler)
{
    if(xy.y == 0 || xy.x >= res.x / kBloomDownsample || xy.y >= res.y / kBloomDownsample)
    {
        return kZero;
    }
    else
    {
        int radius = int(0.5 + float(min(res.x, res.y)) * kBloomRadius.x / float(kBloomDownsample));    
        vec3 sigmaL = kZero, sigmaWeights = kZero;
        for(int k = -radius; k <= radius; ++k)
        {
            ivec2 ij = (xy + ivec2(k, 0)) * kBloomDownsample;
            vec3 texel = texelFetch(sampler, ij, 0).xyz;
            texel = max(kZero, texel - vec3(kBloomBurnout));
            BlurKernel(k, radius, texel, kBloomKernelShape, sigmaL, sigmaWeights);
        }

        return sigmaL / max(kOne, sigmaWeights);
    }
}

vec3 SeparableBlurUp(ivec2 xyFrag, ivec2 res, sampler2D sampler)
{   
    int radius = int(0.5 + float(min(res.x, res.y)) * kBloomRadius.y / float(kBloomDownsample));    
    vec3 sigmaL = kZero, sigmaWeights = kZero;
    for(int k = -radius; k <= radius; ++k)
    {        
        vec2 uv = (vec2(xyFrag + ivec2(0, k * kBloomDownsample)) - 0.5) / vec2(res);

        vec3 texel = texture(sampler, uv / float(kBloomDownsample), 0.0).xyz;

        BlurKernel(k, radius, texel, kBloomKernelShape, sigmaL, sigmaWeights);
    }

    return sigmaL / max(kOne, sigmaWeights);
}


