// Uncomment this line to hide gimbals
#define kShowManipulatorGimbals

// State flags
#define kStateMouseClick       0
#define kStateMouseRayPos      1
#define kStateMouseRayDir      2
#define kStateMouseHitPoint    3
#define kStateRefQuat        4
#define kStateDragQuat       5
#ifdef kShowManipulatorGimbals
    #define kStateGimbalQuatA    6
    #define kStateGimbalQuatB    7
    #define kStateEnd              kStateGimbalQuatB + 1
#else
    #define kStateEnd              kStateDragQuat + 1
#endif

// Utility functions
#define IsManipulatorSelected(state) (texelFetch(state, ivec2(kStateMouseClick, 0), 0).z > 0.)
#define IsMatrixParam(paramIdx, matrixId) (paramIdx >= matrixId && paramIdx < matrixId + 3)
#define IsStateParam(xyPixel) (int(xyPixel.x) < kStateEnd && int(xyPixel.y) == 0)
#define IsMouseStateParam(xyPixel) (int(xyPixel.y) == 0 && int(xyPixel.x) >= kStateMouseRayPos && int(xyPixel.x) <= kStateMouseHitPoint)

// Quaternion multiplication
vec4 QuatMul(vec4 r, vec4 q)
{
    return vec4(r[0]*q[0] - r[1]*q[1] - r[2]*q[2] - r[3]*q[3],
                r[0]*q[1] + r[1]*q[0] - r[2]*q[3] + r[3]*q[2],
                r[0]*q[2] + r[1]*q[3] + r[2]*q[0] - r[3]*q[1],
                r[0]*q[3] - r[1]*q[2] + r[2]*q[1] + r[3]*q[0]);
}

// Unit quarternion to 3x3 rotation matrix
vec4 MatToQuat(mat3 m)
{
    float w = 0.5 * sqrt(1. + m[0][0] + m[1][1] + m[2][2]);
    return vec4(w, 
                (m[2][1] - m[1][2]) / (4.*w),
                (m[0][2] - m[2][0]) / (4.*w),
                (m[1][0] - m[0][1]) / (4.*w));
}

// Axis-angle to unit quaternion
vec4 AxisAngleToQuat(vec3 axis, float theta)
{
    return vec4(cos(theta*0.5), axis * sin(theta*0.5)); 
}

// Unit quarternion to 3x3 rotation matrix
mat3 QuatToMat(vec4 q)
{
    return 2. * mat3(vec3(0.5 - q.z*q.z - q.w*q.w, q.y*q.z + q.x*q.w, q.y*q.w - q.x*q.z),
                     vec3(q.y*q.z - q.x*q.w, 0.5 - q.y*q.y - q.w*q.w, q.z*q.w + q.x*q.y),
                     vec3(q.y*q.w + q.x*q.z, q.z*q.w - q.x*q.y, 0.5 - q.y*q.y - q.z*q.z));
}

// Loads an object manipulator matrix from the corresponding state
mat3 LoadManipulatorMatrix(sampler2D state, int id)
{                   
    return QuatToMat(texelFetch(state, ivec2(id , 0), 0));
}

vec4 LoadManipulatorQuat(sampler2D state, int id)
{                   
    return texelFetch(state, ivec2(id , 0), 0);
}

struct ManipulatorCtx
{
    vec3 cameraPos;
    vec3 objectPos;
    mat3 initMat;
    float speed;
};

void EvaluateManipulatorMatrices(sampler2D state, in int paramIdx, in ManipulatorCtx ctx, inout vec4 rgba)
{
    if(IsManipulatorSelected(state))
    {                
        // Localise the camera position to the object position
        ctx.cameraPos -= ctx.objectPos;

        // Load the hit point of the camera ray plus its position and direction from the state
        vec3 hitPos = texelFetch(state, ivec2(3, 0), 0).xyz - ctx.objectPos;
        RayBasic mouseRay;
        mouseRay.o = texelFetch(state, ivec2(1, 0), 0).xyz - ctx.objectPos;
        mouseRay.d = texelFetch(state, ivec2(2, 0), 0).xyz;

        // Compute the hitpoint of the camera ray with the plane defined by the clicked object hitpoint
        vec3 n = ctx.cameraPos - hitPos;
        float tPlane = (dot(hitPos.xyz, n) - dot(mouseRay.o, n)) / dot(mouseRay.d, n);
        vec3 planePos = PointAt(mouseRay, tPlane);           

        // Define the axis of rotation as the cross product of these two axes
        vec3 rotAxis = normalize(cross(hitPos - ctx.cameraPos, planePos - ctx.cameraPos));   

        // Construct a quaternion using the rotation axis and the distance to the click hitpoint as an angle
        vec4 q = AxisAngleToQuat(rotAxis, ctx.speed  * length(hitPos - planePos));

        // Store the transformation quaternions in the state variables
        if(paramIdx == kStateDragQuat)
        {
            rgba = QuatMul(q, LoadManipulatorQuat(state, kStateRefQuat));
        }  
#ifdef kShowManipulatorGimbals        
        else if(paramIdx == kStateGimbalQuatA)
        {
            rgba = MatToQuat(CreateBasis(normalize(hitPos)));
        }        
        else if(paramIdx == kStateGimbalQuatB)
        {            
            rgba = MatToQuat(CreateBasis(rotAxis));
        }       
#endif
    }

    // If the mouse button has been released, update the reference matrix to the dragging matrix
    if(paramIdx == kStateRefQuat && texelFetch(state, ivec2(0, 0), 0).y != 0.)
    {
        rgba = texelFetch(state, ivec2(kStateDragQuat, 0), 0);
    } 
}

bool UpdateManipulatorState(sampler2D state, int frameIdx, inout vec2 xyScreen, in ManipulatorCtx ctx, in vec4 mouse, inout vec4 rgba)
{ 
    // State variables reference:
    //
    //    0:      click flags: x = dragging, y = mouse released pulse, z = gimbal object selected
    //    1:      mouse ray position
    //    2:      mouse ray direction
    //    3:      mouse ray click hit point
    //    4:      reference rotation matrix
    //    5:      dragging rotation matrix
    //    6-7:    gimbal matrices (optional)

    ivec2 xyPixel = ivec2(xyScreen);
    if(IsStateParam(xyPixel))
    {  
        rgba = texelFetch(state, xyPixel, 0);

        // Mouse status flags
        if(xyPixel.x == kStateMouseClick)
        {           
            // Pulsed to 1 when the mouse button is released (the oppposite of iMouse.w)
            rgba.y = float(mouse.z <= 0. && rgba.x == 1.);
            // Set to 1 when the mouse is dragging
            rgba.x = float(mouse.z > 0.);         
            // Set to 1 if and only the if the mouse is dragging and it was over the gimbal object when the button was originally depressed
            rgba.z = float((bool(rgba.z) || texelFetch(state, ivec2(3, 0), 0).w > 0.) && rgba.y != 1.);            

            rgba.w = (mouse.z > 0. && rgba.z == 1.) ? min(1., rgba.w + 0.05) : max(0., rgba.w - 0.05);

            return true;
        }
        // Mouse ray position, direction and hit point
        else if(IsMouseStateParam(xyPixel))
        {
            xyScreen = mouse.xy;
            return false;
        }
        // Rotation matrices
        else
        {      
            // Initialise the rotation matrix
            if(frameIdx == 0)
            {
                if(xyPixel.x == kStateDragQuat || xyPixel.x == kStateRefQuat)
                {
                    rgba = MatToQuat(ctx.initMat);
                }
                else
                {
                    rgba.xyz *= 0.;
                }
            }

            EvaluateManipulatorMatrices(state, xyPixel.x, ctx, rgba);            
            return true;
        }
    }

    return false;
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    rgba *= 0.;

    // Apply first pass of separable bloom filter
    if(kApplyBloom)
    {    
        rgba = vec4(SeparableBlurDown(ivec2(xyScreen), ivec2(iResolution.xy), iChannel0), 1.);
    }
}

void mainImage( out vec4 rgba, in vec2 xyScreen )
{
    rgba *= 0.;

    // Downsample by integrating sub-pixels (also gives us free anti-aliasing)
    ivec2 xyPixel = ivec2(xyScreen) * kScreenDownsample;
    if(xyPixel.x < int(iResolution.x) && xyPixel.y < int(iResolution.y))
    {
        vec3 sum = kZero;
        for(int y = 0; y < kScreenDownsample; ++y)
        {
            for(int x = 0; x < kScreenDownsample; ++x)
            {
                if(xyPixel.y + y != 0)
                {
                    vec4 texel = texelFetch(iChannel0, xyPixel + ivec2(x, y), 0);
                    sum += texel.xyz / max(1., texel.w);
                }
            }
        }        
        rgba.xyz = sum / float(sqr(kScreenDownsample));
    }
}
